messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>3D Humanoid Animation</title>
    <style>
        body {
            margin: 0;
            overflow: hidden;
            background-color: #87CEEB; /* Sky blue */
        }
        canvas {
            display: block;
        }
        #info {
            position: absolute;
            top: 10px;
            left: 10px;
            color: white;
            font-family: sans-serif;
            font-size: 16px;
            text-shadow: 1px 1px 2px black;
            pointer-events: none;
        }
    </style>
</head>
<body>
    <div id="info">Loading...</div>
    <script type="module">
        import * as THREE from './three.module.js';

        // --- Configuration ---
        const CYCLE_DURATION = 10; // seconds
        const STAGE_STILL_1 = 2;
        const STAGE_WALK = 3;
        const STAGE_RUN = 3;
        const STAGE_STILL_2 = 2;

        // --- Scene Setup ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB);
        scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

        const camera = new THREE.PerspectiveCamera(45, window.innerWidth / window.innerHeight, 0.1, 100);
        camera.position.set(0, 3, 10); // Side-on camera
        camera.lookAt(0, 1.5, 0);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        renderer.shadowMap.enabled = true;
        renderer.shadowMap.type = THREE.PCFSoftShadowMap;
        document.body.appendChild(renderer.domElement);

        // --- Lighting ---
        const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
        scene.add(ambientLight);

        const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
        dirLight.position.set(-5, 10, 5);
        dirLight.castShadow = true;
        dirLight.shadow.mapSize.width = 1024;
        dirLight.shadow.mapSize.height = 1024;
        dirLight.shadow.camera.near = 0.1;
        dirLight.shadow.camera.far = 20;
        dirLight.shadow.camera.left = -5;
        dirLight.shadow.camera.right = 5;
        dirLight.shadow.camera.top = 5;
        dirLight.shadow.camera.bottom = -5;
        scene.add(dirLight);

        // --- Ground / Treadmill ---
        const groundGeo = new THREE.PlaneGeometry(50, 20);
        const groundMat = new THREE.MeshStandardMaterial({ color: 0x2a2a2a, roughness: 0.8 });
        const ground = new THREE.Mesh(groundGeo, groundMat);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -0.01;
        ground.receiveShadow = true;
        scene.add(ground);

        // Treadmill belt visual (stripes)
        const beltGeo = new THREE.PlaneGeometry(50, 2);
        const beltMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, roughness: 0.5 });
        const belt = new THREE.Mesh(beltGeo, beltMat);
        belt.rotation.x = -Math.PI / 2;
        belt.position.y = 0.02;
        belt.receiveShadow = true;
        scene.add(belt);

        // --- Character Construction ---
        const characterGroup = new THREE.Group();
        scene.add(characterGroup);

        // Materials
        const skinMat = new THREE.MeshStandardMaterial({ color: 0xffccaa, flatShading: true });
        const shirtMat = new THREE.MeshStandardMaterial({ color: 0xff4444, flatShading: true });
        const pantsMat = new THREE.MeshStandardMaterial({ color: 0x4444ff, flatShading: true });
        const shoeMat = new THREE.MeshStandardMaterial({ color: 0x222222, flatShading: true });

        // Helper to create limb
        function createLimb(w, h, d, x, y, z, material) {
            const geo = new THREE.BoxGeometry(w, h, d);
            const mesh = new THREE.Mesh(geo, material);
            mesh.position.set(x, y, z);
            mesh.castShadow = true;
            return mesh;
        }

        // Torso
        const torso = createLimb(0.8, 1.2, 0.5, 0, 2.2, 0, shirtMat);
        characterGroup.add(torso);

        // Head
        const head = createLimb(0.5, 0.5, 0.5, 0, 3.0, 0, skinMat);
        characterGroup.add(head);

        // Hips (Pivot point for torso lean)
        const hips = new THREE.Group();
        hips.position.set(0, 1.5, 0);
        characterGroup.add(hips);

        // Re-parent torso and head to hips for lean effect
        torso.position.set(0, 0.7, 0);
        head.position.set(0, 1.5, 0);
        hips.add(torso);
        hips.add(head);

        // Legs
        const legLength = 1.5;
        const thighH = 0.7;
        const shinH = 0.7;
        const footH = 0.15;

        // Left Leg
        const leftHipJoint = new THREE.Group();
        leftHipJoint.position.set(-0.3, 0, 0);
        hips.add(leftHipJoint);

        const leftThigh = createLimb(0.35, thighH, 0.4, 0, -thighH/2, 0, pantsMat);
        leftHipJoint.add(leftThigh);

        const leftKneeJoint = new THREE.Group();
        leftKneeJoint.position.set(0, -thighH, 0);
        leftThigh.add(leftKneeJoint);

        const leftShin = createLimb(0.3, shinH, 0.35, 0, -shinH/2, 0, pantsMat);
        leftKneeJoint.add(leftShin);

        const leftFoot = createLimb(0.32, footH, 0.5, 0, -shinH - footH/2, 0.1, shoeMat);
        leftKneeJoint.add(leftFoot);

        // Right Leg
        const rightHipJoint = new THREE.Group();
        rightHipJoint.position.set(0.3, 0, 0);
        hips.add(rightHipJoint);

        const rightThigh = createLimb(0.35, thighH, 0.4, 0, -thighH/2, 0, pantsMat);
        rightHipJoint.add(rightThigh);

        const rightKneeJoint = new THREE.Group();
        rightKneeJoint.position.set(0, -thighH, 0);
        rightThigh.add(rightKneeJoint);

        const rightShin = createLimb(0.3, shinH, 0.35, 0, -shinH/2, 0, pantsMat);
        rightKneeJoint.add(rightShin);

        const rightFoot = createLimb(0.32, footH, 0.5, 0, -shinH - footH/2, 0.1, shoeMat);
        rightKneeJoint.add(rightFoot);

        // Arms
        const armLength = 1.2;
        const upperArmH = 0.6;
        const forearmH = 0.6;
        const handH = 0.2;

        // Left Arm
        const leftShoulderJoint = new THREE.Group();
        leftShoulderJoint.position.set(-0.5, 1.0, 0);
        torso.add(leftShoulderJoint);

        const leftUpperArm = createLimb(0.25, upperArmH, 0.3, 0, -upperArmH/2, 0, skinMat);
        leftShoulderJoint.add(leftUpperArm);

        const leftElbowJoint = new THREE.Group();
        leftElbowJoint.position.set(0, -upperArmH, 0);
        leftUpperArm.add(leftElbowJoint);

        const leftForearm = createLimb(0.2, forearmH, 0.25, 0, -forearmH/2, 0, skinMat);
        leftElbowJoint.add(leftForearm);

        const leftHand = createLimb(0.22, handH, 0.22, 0, -forearmH - handH/2, 0, skinMat);
        leftElbowJoint.add(leftHand);

        // Right Arm
        const rightShoulderJoint = new THREE.Group();
        rightShoulderJoint.position.set(0.5, 1.0, 0);
        torso.add(rightShoulderJoint);

        const rightUpperArm = createLimb(0.25, upperArmH, 0.3, 0, -upperArmH/2, 0, skinMat);
        rightShoulderJoint.add(rightUpperArm);

        const rightElbowJoint = new THREE.Group();
        rightElbowJoint.position.set(0, -upperArmH, 0);
        rightUpperArm.add(rightElbowJoint);

        const rightForearm = createLimb(0.2, forearmH, 0.25, 0, -forearmH/2, 0, skinMat);
        rightElbowJoint.add(rightForearm);

        const rightHand = createLimb(0.22, handH, 0.22, 0, -forearmH - handH/2, 0, skinMat);
        rightElbowJoint.add(rightHand);

        // --- Animation Logic ---
        const clock = new THREE.Clock();
        const infoDiv = document.getElementById('info');

        function animate() {
            requestAnimationFrame(animate);

            const elapsed = clock.getElapsedTime();
            const cycleTime = elapsed % CYCLE_DURATION;

            // Determine Stage
            let stage = '';
            let stageTime = 0;

            if (cycleTime < STAGE_STILL_1) {
                stage = 'STILL';
                stageTime = cycleTime;
            } else if (cycleTime < STAGE_STILL_1 + STAGE_WALK) {
                stage = 'WALK';
                stageTime = cycleTime - STAGE_STILL_1;
            } else if (cycleTime < STAGE_STILL_1 + STAGE_WALK + STAGE_RUN) {
                stage = 'RUN';
                stageTime = cycleTime - STAGE_STILL_1 - STAGE_WALK;
            } else {
                stage = 'STILL_2';
                stageTime = cycleTime - STAGE_STILL_1 - STAGE_WALK - STAGE_RUN;
            }

            infoDiv.textContent = `Time: ${cycleTime.toFixed(1)}s | Stage: ${stage}`;

            // Reset to default pose
            hips.rotation.x = 0;
            leftHipJoint.rotation.x = 0;
            rightHipJoint.rotation.x = 0;
            leftKneeJoint.rotation.x = 0;
            rightKneeJoint.rotation.x = 0;
            leftShoulderJoint.rotation.x = 0;
            rightShoulderJoint.rotation.x = 0;
            leftElbowJoint.rotation.x = 0;
            rightElbowJoint.rotation.x = 0;

            if (stage === 'STILL' || stage === 'STILL_2') {
                // Subtle breathing
                const breath = Math.sin(elapsed * 2) * 0.02;
                torso.scale.y = 1 + breath;
                torso.scale.x = 1 + breath * 0.5;
            } else if (stage === 'WALK') {
                // Walk Animation
                const walkSpeed = 3.5; // Radians per second
                const phase = stageTime * walkSpeed;
                const ampHip = 0.4;
                const ampKnee = 0.3;
                const ampShoulder = 0.3;
                const ampElbow = 0.2;

                // Hips Bob
                const hipBob = Math.abs(Math.sin(phase)) * 0.05;
                hips.position.y = 1.5 - hipBob;

                // Legs
                leftHipJoint.rotation.x = Math.sin(phase) * ampHip;
                rightHipJoint.rotation.x = Math.sin(phase + Math.PI) * ampHip;

                leftKneeJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI/2) * ampKnee);
                rightKneeJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI + Math.PI/2) * ampKnee);

                // Arms
                leftShoulderJoint.rotation.x = Math.sin(phase) * ampShoulder;
                rightShoulderJoint.rotation.x = Math.sin(phase + Math.PI) * ampShoulder;

                leftElbowJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI/2) * ampElbow);
                rightElbowJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI + Math.PI/2) * ampElbow);

                // Torso Lean (Slight forward)
                hips.rotation.x = 0.05;

            } else if (stage === 'RUN') {
                // Run Animation
                const runSpeed = 6.0;
                const phase = stageTime * runSpeed;
                const ampHip = 0.8;
                const ampKnee = 0.6;
                const ampShoulder = 0.6;
                const ampElbow = 0.8;

                // Hips Bob (More pronounced)
                const hipBob = Math.abs(Math.sin(phase)) * 0.15;
                hips.position.y = 1.5 - hipBob;

                // Legs (Higher lift, faster)
                leftHipJoint.rotation.x = Math.sin(phase) * ampHip;
                rightHipJoint.rotation.x = Math.sin(phase + Math.PI) * ampHip;

                leftKneeJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI/2) * ampKnee);
                rightKneeJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI + Math.PI/2) * ampKnee);

                // Arms (Swing more, bend more)
                leftShoulderJoint.rotation.x = Math.sin(phase) * ampShoulder;
                rightShoulderJoint.rotation.x = Math.sin(phase + Math.PI) * ampShoulder;

                leftElbowJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI/2) * ampElbow);
                rightElbowJoint.rotation.x = Math.max(0, Math.sin(phase + Math.PI + Math.PI/2) * ampElbow);

                // Torso Lean (Significant forward lean)
                hips.rotation.x = 0.2;
            }

            renderer.render(scene, camera);
        }

        // Handle Resize
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        // Start
        animate();
    </script>
</body>
</html>
```
